function takeSmallestGame(nums: number[]): number[] {
  const left = nums.slice(), result: number[] = [];
  const takeMin = () => {
    let at = 0;
    for (let i = 1; i < left.length; i++) if (left[i] < left[at]) at = i;
    return left.splice(at, 1)[0];
  };
  while (left.length > 0) {
    const ada = takeMin(), ben = takeMin();
    result.push(ben, ada);
  }
  return result;
}

