class MinHeap {
  private a: number[] = [];
  get size() { return this.a.length; }
  push(v: number): void {
    const a = this.a;
    a.push(v);
    let i = a.length - 1;
    while (i > 0) {
      const p = (i - 1) >> 1;
      if (a[p] <= a[i]) break;
      [a[p], a[i]] = [a[i], a[p]];
      i = p;
    }
  }
  pop(): number {
    const a = this.a, top = a[0], last = a.pop()!;
    if (a.length > 0) {
      a[0] = last;
      let i = 0;
      for (;;) {
        const l = 2 * i + 1, r = l + 1;
        let m = i;
        if (l < a.length && a[l] < a[m]) m = l;
        if (r < a.length && a[r] < a[m]) m = r;
        if (m === i) break;
        [a[m], a[i]] = [a[i], a[m]];
        i = m;
      }
    }
    return top;
  }
}

function takeSmallestGame(nums: number[]): number[] {
  const heap = new MinHeap();
  for (const v of nums) heap.push(v);
  const result: number[] = [];
  while (heap.size > 0) {
    const ada = heap.pop(), ben = heap.pop();
    result.push(ben, ada);
  }
  return result;
}

